Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Time t: <output id="timeSliderVal">2.2</output>
  <input id="timeSliderInput" type="range" min="-2" max="8" step="0.1" value="2.2"
