// @FIGURE_CODE_BEGIN
(function () {
  var C = 100, A = 9;
  var XMIN = -2.5, XMAX = 8.5, YMIN = -15, YMAX = 115;
  var BLUE = '#1d4e89', ORANGE = '#e2571b', RED = '#d62728';
  var currentB = 1, currentT = 2.2, showTangent = false;

  function fval(t, b) { return C / (1 + A * Math.exp(-b * t)); }
  function fderiv(t, b) { var f = fval(t, b); return b * f * (1 - f / C); }
  function inflT(b) { return Math.log(A) / b; }
  function curvePts(b) {
    var pts = [], n = 240;
    for (var i = 0; i <= n; i++) { var t = XMIN + (XMAX - XMIN) * i / n; pts.push({ x: t, y: fval(t, b) }); }
    return pts;
  }

  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  document.getElementById('container').appendChild(canvas);

  function halo(ctx, txt, x, y, fill, font, align) {
    ctx.save(); ctx.font = font; ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
    ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(255,255,255,0.92)'; ctx.lineJoin = 'round';
    ctx.strokeText(txt, x, y); ctx.fillStyle = fill; ctx.fillText(txt, x, y); ctx.restore();
  }
  function arrow(ctx, x1, y1, x2, y2, col, w) {
    ctx.save(); ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = w || 1.3;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    var ang = Math.atan2(y2 - y1, x2 - x1), h = 7;
    ctx.beginPath(); ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - h * Math.cos(ang - 0.4), y2 - h * Math.sin(ang - 0.4));
    ctx.lineTo(x2 - h * Math.cos(ang + 0.4), y2 - h * Math.sin(ang + 0.4));
    ctx.closePath(); ctx.fill(); ctx.restore();
  }
  function axisArrow(ctx, x1, y1, x2, y2, col, w, hl) {
    ctx.save(); ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = w;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    var ang = Math.atan2(y2 - y1, x2 - x1);
    ctx.beginPath(); ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - hl * Math.cos(ang - 0.42), y2 - hl * Math.sin(ang - 0.42));
    ctx.lineTo(x2 - hl * Math.cos(ang + 0.42), y2 - hl * Math.sin(ang + 0.42));
    ctx.closePath(); ctx.fill(); ctx.restore();
  }
  // stacked fraction: draws num over den centered at left x, vertical center yc; returns width
  function drawFrac(ctx, num, den, x, yc, numFont, denFont, color) {
    ctx.save(); ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.font = numFont; var nw = ctx.measureText(num).width;
    ctx.font = denFont; var dw = ctx.measureText(den).width;
    var w = Math.max(nw, dw) + 4, cx = x + w / 2;
    ctx.font = numFont; ctx.fillText(num, cx, yc - 3);
    ctx.font = denFont; ctx.fillText(den, cx, yc + 12);
    ctx.strokeStyle = color; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x, yc); ctx.lineTo(x + w, yc); ctx.stroke();
    ctx.restore(); return w;
  }
  // main formula f(t) = c / (1 + a e^{-bx}) as a real stacked fraction with raised exponent
  function drawFormula(ctx, x, yc, color, fs) {
    var it = 'italic ' + fs + 'px Georgia, serif';
    var small = 'italic ' + Math.round(fs * 0.72) + 'px Georgia, serif';
    ctx.save(); ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';
    ctx.font = it; ctx.fillStyle = color;
    var pre = 'f(t) = '; ctx.fillText(pre, x, yc + 4); var px = x + ctx.measureText(pre).width;
    // denominator pieces
    ctx.font = it; var dMain = '1 + ae'; var dMainW = ctx.measureText(dMain).width;
    ctx.font = small; var dSup = '\u2212bx'; var dSupW = ctx.measureText(dSup).width;
    var denW = dMainW + dSupW;
    ctx.font = it; var numW = ctx.measureText('c').width;
    var w = Math.max(numW, denW) + 6, cx = px + w / 2;
    // numerator
    ctx.font = it; ctx.textAlign = 'center'; ctx.fillText('c', cx, yc - 4);
    // bar
    ctx.strokeStyle = color; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(px, yc); ctx.lineTo(px + w, yc); ctx.stroke();
    // denominator main + raised exponent
    ctx.textAlign = 'left'; ctx.font = it; ctx.fillText(dMain, px + 2, yc + 13);
    ctx.font = small; ctx.fillText(dSup, px + 2 + dMainW, yc + 9);
    ctx.restore();
  }

  var annot = {
    id: 'logisticAnnot',
    beforeDatasetsDraw: function (chart) {
      var ctx = chart.ctx, ca = chart.chartArea;
      var px = function (t) { return chart.scales.x.getPixelForValue(t); };
      var py = function (f) { return chart.scales.y.getPixelForValue(f); };
      var base = Math.min(chart.width, chart.height);
      var hl = Math.max(7, Math.min(13, base * 0.022));
      var axw = Math.max(1.2, base * 0.0022);
      ctx.save(); ctx.setLineDash([7, 5]); ctx.strokeStyle = ORANGE; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(ca.left, py(C)); ctx.lineTo(ca.right, py(C)); ctx.stroke();
      ctx.setLineDash([]); ctx.restore();
      axisArrow(ctx, px(XMAX), py(0), px(XMIN), py(0), '#111', axw, hl);
      axisArrow(ctx, px(XMIN), py(0), px(XMAX), py(0), '#111', axw, hl);
      axisArrow(ctx, px(0), py(YMAX), px(0), py(YMIN), '#111', axw, hl);
      axisArrow(ctx, px(0), py(YMIN), px(0), py(YMAX), '#111', axw, hl);
    },
    afterDraw: function (chart) {
      var ctx = chart.ctx, ca = chart.chartArea;
      var px = function (t) { return chart.scales.x.getPixelForValue(t); };
      var py = function (f) { return chart.scales.y.getPixelForValue(f); };
      var base = Math.min(chart.width, chart.height);
      var fs = Math.max(11, Math.min(15, base * 0.026));
      var fsS = Math.max(9, Math.min(12, base * 0.02));
      var it = 'italic ' + fs + 'px Georgia, serif';
      var fr = fs + 'px sans-serif';
      var frS = (fs - 1) + 'px sans-serif';
      var itS = 'italic ' + (fs - 1) + 'px Georgia, serif';
      var axisY = py(0);
      var itPt = inflT(currentB);

      // axis end labels
      halo(ctx, 't', px(XMAX) - 4, axisY - 8, '#111', it, 'right');
      halo(ctx, 'f(t)', px(0) + 8, py(YMAX) + 14, '#111', it, 'left');
      halo(ctx, 'y = c', ca.left + 6, py(C) - 7, ORANGE, it, 'left');

      // carrying capacity leader
      var ccx = px(3.0), ccy = py(C);
      var ccTx = ca.left + ca.width * 0.40, ccTy = ca.top + 16;
      arrow(ctx, ccTx + 4, ccTy + 4, ccx, ccy, '#111', 1.3);
      halo(ctx, 'Carrying capacity', ccTx, ccTy, '#111', fr, 'left');

      // formula as stacked fraction (blue, right of upper bend)
      drawFormula(ctx, px(4.55), py(93), BLUE, fs);

      // landmark dots (always visible)
      var d0x = px(0), d0y = py(fval(0, currentB));
      var dix = px(itPt), diy = py(C / 2);
      ctx.save(); ctx.fillStyle = BLUE; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(d0x, d0y, 5, 0, 7); ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.arc(dix, diy, 5, 0, 7); ctx.fill(); ctx.stroke(); ctx.restore();

      // coordinate label (0, c/(1+a)) as stacked fraction, upper-left of dot
      (function () {
        ctx.save(); ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';
        ctx.font = frS; ctx.fillStyle = '#111';
        var openW = ctx.measureText('(0, ').width;
        var sx = d0x - 14 - openW - 46; // reserve
        sx = d0x - 12 - openW - 40;
        var yc = d0y - 12;
        ctx.strokeStyle = 'rgba(255,255,255,0.92)'; ctx.lineWidth = 3; ctx.lineJoin = 'round';
        ctx.strokeText('(0, ', sx, yc + 4); ctx.fillText('(0, ', sx, yc + 4);
        var fw = drawFrac(ctx, 'c', '1 + a', sx + openW, yc, itS, frS, '#111');
        var cx2 = sx + openW + fw;
        ctx.font = frS; ctx.strokeText(')', cx2 + 1, yc + 4); ctx.fillText(')', cx2 + 1, yc + 4);
        ctx.restore();
      })();

      // leader + label "Initial value of population" — raised above the t-axis
      var ivTx = d0x + 26, ivTy = axisY - 8;
      arrow(ctx, ivTx - 4, ivTy - 10, d0x + 4, d0y + 4, '#111', 1.3);
      halo(ctx, 'Initial value of population', ivTx, ivTy, '#111', fr, 'left');

      // coordinate label (ln(a)/b, c/2) as stacked fractions, right of inflection dot
      (function () {
        ctx.save(); ctx.textBaseline = 'alphabetic'; ctx.textAlign = 'left';
        var sx = dix + 14, yc = diy - 10;
        ctx.font = frS; ctx.fillStyle = '#111';
        ctx.strokeStyle = 'rgba(255,255,255,0.92)'; ctx.lineWidth = 3; ctx.lineJoin = 'round';
        ctx.strokeText('(', sx, yc + 4); ctx.fillText('(', sx, yc + 4);
        var x2 = sx + ctx.measureText('(').width;
        var fw1 = drawFrac(ctx, 'ln(a)', 'b', x2, yc, itS, frS, '#111');
        x2 += fw1;
        ctx.font = frS; ctx.strokeText(', ', x2, yc + 4); ctx.fillText(', ', x2, yc + 4);
        x2 += ctx.measureText(', ').width;
        var fw2 = drawFrac(ctx, 'c', '2', x2, yc, itS, frS, '#111');
        x2 += fw2;
        ctx.font = frS; ctx.strokeText(')', x2 + 1, yc + 4); ctx.fillText(')', x2 + 1, yc + 4);
        ctx.restore();
      })();

      // leader + label "Point of maximum growth"
      var mgTx = dix + 22, mgTy = diy + 46;
      arrow(ctx, mgTx - 2, mgTy - 12, dix + 4, diy + 4, '#111', 1.3);
      halo(ctx, 'Point of maximum growth', mgTx, mgTy, '#111', fr, 'left');

      // tangent + marker + readout only when enabled
      if (showTangent) {
        var f0 = fval(currentT, currentB), m = fderiv(currentT, currentB), dt = 1.3;
        var tx1 = px(currentT - dt), ty1 = py(f0 - m * dt);
        var tx2 = px(currentT + dt), ty2 = py(f0 + m * dt);
        ctx.save(); ctx.strokeStyle = RED; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(tx1, ty1); ctx.lineTo(tx2, ty2); ctx.stroke(); ctx.restore();
        ctx.save(); ctx.fillStyle = RED; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.arc(px(currentT), py(f0), 5, 0, 7); ctx.fill(); ctx.stroke(); ctx.restore();

        var bw = Math.max(120, base * 0.22), bh = 56;
        var bx = ca.right - bw - 10, by = ca.bottom - bh - 70;
        ctx.save(); ctx.fillStyle = 'rgba(255,255,255,0.9)'; ctx.strokeStyle = '#bbb'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.rect(bx, by, bw, bh); ctx.fill(); ctx.stroke(); ctx.restore();
        halo(ctx, 'f(t) = ' + f0.toFixed(1), bx + 8, by + 18, '#111', fsS + 'px sans-serif', 'left');
        halo(ctx, 'slope = ' + m.toFixed(2), bx + 8, by + 34, RED, fsS + 'px sans-serif', 'left');
        halo(ctx, 'c \u2212 f(t) = ' + (C - f0).toFixed(1), bx + 8, by + 50, ORANGE, fsS + 'px sans-serif', 'left');
      }
    }
  };

  var chart = new Chart(canvas, {
    type: 'scatter',
    data: {
      datasets: [
        { type: 'line', label: 'logistic', data: curvePts(currentB), borderColor: BLUE,
          borderWidth: 2.6, pointRadius: 0, fill: false, tension: 0, order: 3 }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: { type: 'linear', min: XMIN, max: XMAX, ticks: { display: false }, grid: { display: false }, border: { display: false } },
        y: { type: 'linear', min: YMIN, max: YMAX, ticks: { display: false }, grid: { display: false }, border: { display: false } }
      }
    },
    plugins: [annot]
  });
  window.__markRendered();

  function rebuildCurve() { chart.data.datasets[0].data = curvePts(currentB); chart.update('none'); }

  window.update_timeSlider = function (v) { currentT = v; chart.update('none'); };
  window.update_growthRateSlider = function (v) { currentB = v; rebuildCurve(); };
  window.toggle_showTangent = function (on) { showTangent = on; chart.update('none'); };

  var steps = [
    { title: 'Read the three landmarks',
      narration: 'The curve starts at the initial value c/(1+a) on the vertical axis, climbs steepest at the inflection point (ln(a)/b, c/2), and levels off toward the dashed carrying-capacity line y = c without ever touching it.',
      state: { timeSlider: 2.2, growthRateSlider: 1, showTangent: false } },
    { title: 'Sweep time to feel the slope',
      narration: 'Drag the time slider: the tangent is steepest when the marker sits at c/2, then flattens as the gap c \u2212 f(t) closes, making visible that the growth rate peaks at half capacity and then decays.',
      state: { timeSlider: 6, growthRateSlider: 1, showTangent: true } },
    { title: 'Change the growth rate b',
      narration: 'Raise or lower b and watch the whole S-curve steepen or flatten while the maximum-growth dot slides horizontally, showing that b controls how abruptly the population makes its transition toward saturation.',
      state: { timeSlider: 2.2, growthRateSlider: 2.5, showTangent: true } }
  ];
  var stepIdx = 0;
  function applyStep(i) {
    stepIdx = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[stepIdx];
    document.getElementById('timeSliderInput').value = s.state.timeSlider;
    document.getElementById('timeSliderVal').value = s.state.timeSlider;
    document.getElementById('growthRateSliderInput').value = s.state.growthRateSlider;
    document.getElementById('growthRateSliderVal').value = s.state.growthRateSlider;
    document.getElementById('showTangentInput').checked = s.state.showTangent;
    currentB = s.state.growthRateSlider; currentT = s.state.timeSlider; showTangent = s.state.showTangent;
    rebuildCurve();
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length + ' \u00B7 ' + s.title;
  }
  window.nextStep = function () { applyStep(stepIdx + 1); };
  window.prevStep = function () { applyStep(stepIdx - 1); };
  applyStep(0);
})();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

